function cycleGraphic(){return `<svg viewBox="0 0 400 325" role="img" aria-label="${esc(t('schematic'))}"><defs><radialGradient id="cyGlow"><stop stop-color="#c9dccf" stop-opacity=".5"/><stop offset="1" stop-color="#c9dccf" stop-opacity="0"/></radialGradient></defs><circle cx="204" cy="157" r="145" fill="url(#cyGlow)"/><circle cx="204" cy="157" r="108" fill="none" stroke="currentColor" opacity=".1"/><circle cx="204" cy="157" r="80" fill="none" stroke="currentColor" opacity=".13" stroke-dasharray="2 7"/><g class="cycle-orbit"><ellipse cx="204" cy="157" rx="125" ry="46" fill="none" stroke="#88aa93" stroke-width=".7" transform="rotate(-30 204 157)"/><ellipse cx="204" cy="157" rx="125" ry="46" fill="none" stroke="#88aa93" stroke-width=".7" transform="rotate(30 204 157)"/></g><circle cx="204" cy="157" r="52" fill="var(--surface)" stroke="#b9cbbd"/><text x="204" y="154" text-anchor="middle" fill="var(--text)" font-family="Georgia,serif" font-size="24" font-style="italic">S. cerevisiae</text><text x="204" y="176" text-anchor="middle" fill="var(--muted)" font-size="9" letter-spacing="2">CELL CYCLE</text>${[['G1',204,49,'#347a5a'],['S',309,136,'#8b73a9'],['G2/M',250,254,'#aa8247'],['M/G1',105,221,'#567ca4']].map(([label,x,y,c])=>`<circle cx="${x}" cy="${y}" r="23" fill="var(--surface)" stroke="${c}"/><circle cx="${x}" cy="${y}" r="18" fill="${c}" fill-opacity=".08"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="11" fill="${c}">${label}</text>`).join('')}<circle cx="107" cy="107" r="5" fill="#80a68b"/><circle cx="302" cy="213" r="4" fill="#a591b9"/><circle cx="173" cy="261" r="3" fill="#c8ac78"/><text x="204" y="314" text-anchor="middle" fill="var(--muted)" font-size="9" letter-spacing="1">${esc(t('schematic'))}</text></svg>`;}
